3	55.752784	37.819307	г. Москва, Свободный проспект 33	Пункт приема электротехники и батареек в магазине Мвидео	Находится в ТЦ "Кунцево Плаза". Принимается для переработки электроника, отслужившая техника,телефоны. Собранная техника отправится на завод "Экополис" для переработки. Подробнее: http://www.ecopoliscorp.com/pressroom/news/startoval-samyy-krupnyy-v-rossii-proekt-po-postoyannomu-sboru-i-utilizatsii-bytovoy-tekhniki-i-elekt/\r\nТакже принимаются любые батарейки и аккумуляторы, кроме свинцово-кислотных автомобильных аккумуляторов и аккумуляторов от источников бесперебойного питания, имеющих надпись Lead Acid. Собранные батарейки и аккумуляторы отправляются на крупнейший завод по переработке опасных отходов " Мегаполисресурс". Подробнее: \r\nhttps://eco2eco.ru/blog/mvideo-sobiraet-batareyki.html	f	BATAREJKI	{"Friday": "09:00 - 22:00", "Monday": "09:00 - 22:00", "Sunday": "09:00 - 22:00", "Tuesday": "09:00 - 22:00", "Saturday": "09:00 - 22:00", "Thursday": "09:00 - 22:00", "Wednesday": "09:00 - 22:00"}	2025-03-28 09:39:51.36479+00
2	55.72555399999998	37.463826	г. Москва, Славянский бульвар 13с1	Пункт приема электротехники и батареек в магазине Мвидео	Принимается для переработки старая техника: смартфоны, компьютеры, сетевые устройства, серверы, ноутбуки, мониторы, МФУ, принтеры, плоттеры, телефоны, МР3-устройства, пылесосы,видеокамеры, цифровые камеры, холодильники, телевизоры, стиральные машины и др. Собранная техника отправится на завод "Экополис" для переработки. Подробнее: http://www.ecopoliscorp.com/pressroom/news/startoval-samyy-krupnyy-v-rossii-proekt-po-postoyannomu-sboru-i-utilizatsii-bytovoy-tekhniki-i-elekt/. \r\nТакже принимаются любые батарейки и аккумуляторы, кроме свинцово-кислотных автомобильных аккумуляторов и аккумуляторов от источников бесперебойного питания, имеющих надпись Lead Acid. Собранные батарейки и аккумуляторы отправляются на крупнейший завод по переработке опасных отходов "Мегаполисресурс". Подробнее: \r\nhttps://eco2eco.ru/blog/mvideo-sobiraet-batareyki.html	f	BATAREJKI	{"Friday": "00:00 - 23:59", "Monday": "00:00 - 23:59", "Sunday": "00:00 - 23:59", "Tuesday": "00:00 - 23:59", "Saturday": "00:00 - 23:59", "Thursday": "00:00 - 23:59", "Wednesday": "00:00 - 23:59"}	2025-03-28 09:39:51.36339+00
